from functools import wraps
import re
from taf.sw.nrdim.javascript_executor import JavaScriptExecutor
from taf.sw.nrdim.utils import add_function_trace
from taf.sw.nrdim.exceptions import ScfParameterNotExist, GetScfInputInvalid


def logging_decorator(convert_func):

    @wraps(convert_func)
    def convert_wrapper(convertor, *args, **kwargs):
        value = convert_func(convertor, *args, **kwargs)
        logging.debug('convert nrdim param "{}" to {}'.format(convertor.name, value))
        return value

    return convert_wrapper


class BaseConvertor(object):

    name = ""

    def __init__(self, scf_query, scf_mediation, cell_distname, cellgroup_distname):
        self._scf = scf_query
        self._scf_mediation = scf_mediation
        self._cell_distname = cell_distname
        self._cellgroup_distname = cellgroup_distname

    @abstractmethod
    def convert(self):
        raise NotImplementedError

    @add_function_trace
    def _get_mediation_value_index(self, name, scf_value):
        mediation_table = self._get_mediation_values(name)
        if not mediation_table or scf_value not in mediation_table:
            logging.debug("{}:{} not in mediation table {}".format(name, scf_value, mediation_table))
            return None

        mediation_value = mediation_table[scf_value]
        return list(mediation_table.values()).index(mediation_value)

    @add_function_trace
    def _get_mediated_attribute_value(self, scf_name, scf_value, nrdim_name):
        mediation_values = self._get_mediation_values(scf_name)
        if scf_value not in mediation_values:
            return None

        value = mediation_values[scf_value]

        mediated_attributes = self._get_mediated_attributes(scf_name)
        if nrdim_name not in mediated_attributes:
            return value

        attribute_value_expression = mediated_attributes[nrdim_name]
        attribute_value_expression = attribute_value_expression.replace("value", str(value))
        return JavaScriptExecutor.execute(attribute_value_expression)

    @add_function_trace
    def _get_mediation_values(self, name):
        mediation_table = self._get_mediation_table(name)
        if mediation_table is None or 'mediationValues' not in mediation_table:
            logging.debug("{} do not have mediation values table".format(name))
            return None

        return mediation_table['mediationValues']

    @add_function_trace
    def _get_mediated_attributes(self, name):
        mediation_table = self._get_mediation_table(name)
        if mediation_table is None or 'mediatedAttributes' not in mediation_table:
            logging.debug("{} do not have mediated attributes table".format(name))
            return None

        return mediation_table['mediatedAttributes']

    @add_function_trace
    def _get_mediation_table(self, name):
        if name not in self._scf_mediation:
            logging.debug("{} not in scf mediation".format(name))
            return None

        return self._scf_mediation[name]

    @add_function_trace
    def _get_scf_parameter_value(self, name,
                                 cell_distname=None,
                                 cellgroup_distname=None,
                                 profile_distname=None,
                                 **kwargs):
        if cell_distname and cellgroup_distname and profile_distname:
            raise GetScfInputInvalid("cell_distname {} and cellgroup_distname {}".format(cell_distname, cellgroup_distname))

        dist_name = cell_distname or cellgroup_distname or profile_distname

        value = self._scf.get_parameter_value(name, dist_name=dist_name, **kwargs)
        logging.debug("get scf {} = {} dist_name={}".format(name, value, dist_name))
        if value is None:
            raise ScfParameterNotExist
        return value


class GeneralConvertor(BaseConvertor):

    def __init__(self, name, **kwargs):
        self.name = name
        super(GeneralConvertor, self).__init__(**kwargs)

    @logging_decorator
    def convert(self):
        try:
            scf_value = self._get_scf_parameter_value(self.name)
        except ScfParameterNotExist:
            return None
        return self._get_mediation_value_index(self.name, scf_value)


class FreqRange(BaseConvertor):

    name = "freqRange"

    """
    The freqRange attribute is a 3GPP notion (may be linked to µ in 38 series).
    If NRCELL.cellTechnology is equal to 1 (corresponding to TDD) and if NRCELL.nrarfcn <= 800000,
    then freqRange = TDD FR1.
    If NRCELL.cellTechnology is equal to 1 (corresponding to TDD) and if NRCELL.nrarfcn >= 2016667,
    then freqRange = TDD FR2.
    If NRCELL.cellTechnology is equal to 0, then freqRange = FDD.
    """

    @logging_decorator
    def convert(self):
        cell_technology = self._get_scf_parameter_value("cellTechnology", cell_distname=self._cell_distname)
        nrdim_index = 0
        if cell_technology == "TDD":
            nrarfcn = self._get_scf_parameter_value("nrarfcn", cell_distname=self._cell_distname)
            if int(nrarfcn) <= 800000:
                nrdim_index = 0
            elif int(nrarfcn) >= 2016667:
                nrdim_index = 1
        else:
            nrdim_index = 2

        return nrdim_index


class GlobalPeriodicity(BaseConvertor):

    name = "globalPeriodicity"

    """
    This parameter will determine the number of slots generated by the tool.
    """

    @logging_decorator
    def convert(self):
        return 4  # 160ms


class DLBandwidth(BaseConvertor):

    name = "DLBandwidth"

    """
    Channel bandwidth defines the bandwidth for the gNB transmission in a cell.
    In TDD, this refers to chBw.
    In FDD, this refers to chBwDl.
    """

    @logging_decorator
    def convert(self):
        try:
            bandwidth = self._get_scf_parameter_value("chBw", cell_distname=self._cell_distname)
        except ScfParameterNotExist:
            bandwidth = self._get_scf_parameter_value(
                "chBwDl", cell_distname="{}/{}".format(self._cell_distname, "NRCELL_FDD-1"))

        bandwidth_with_space = re.sub(r'(\d+\.?\d*)([A-Za-z]+)', r'\1 \2', bandwidth)
        for bandwidth_value in [bandwidth, bandwidth.replace(" ", ""), bandwidth_with_space]:
            mediation_value_index = self._get_mediation_value_index("bandwidth", bandwidth_value)
            if mediation_value_index is None:
                continue
            return mediation_value_index
        return None


