class RachFDM(BaseConvertor):

    name = "rachFDM"

    """
    Activation flag for PRACH slot uplink channel multiplexing.
    This parameter is called actPrachMultiplexing at NIDD level.

    when pucch mode is longPucch, force rachFDM is Enable.
    """

    @logging_decorator
    def convert(self):
        try:
            pucch_mode = self._get_scf_parameter_value("pucchModeSelect", cell_distname=self._cell_distname)
            if pucch_mode == "longPucch":
                return 1
        except ScfParameterNotExist:
            logging.info("'pucchModeSelect' not found in SCF, default 'shortPucch'")

        scf_value = self._get_scf_parameter_value("actPrachMultiplexing", cell_distname=self._cell_distname)
        return int(scf_value == "true")


