class CsicbType(BaseConvertor):

    name = "csicbType"

    """
    Adds refined beams. Required when actBeamforming is enabled.
    This is called csirsBmMgmtSubband at NIDD level.
    "csirsBmMgmtSubband": {
        "check": {
            "attribute": "nrBtsBeamRefinementP2",
            "equals": "true"
        },
        "mediationValues": {
            "belowSSPBCHBlock": 1,
            "aboveSSPBCHBlock": 2
        },
        "defaultValue": 0,
        "mediatedAttributes": {
                "csicbType": "value"
        }
    }
    """

    @logging_decorator
    def convert(self):
        try:
            scf_value = self._get_scf_parameter_value("nrBtsBeamRefinementP2", cell_distname=self._cell_distname)
            if scf_value == "false":
                return 0
        except ScfParameterNotExist:
            return 0

        try:
            scf_value = self._get_scf_parameter_value("csirsBmMgmtSubband", cell_distname=self._cell_distname)
        except ScfParameterNotExist:
            return 0

        return self._get_mediated_attribute_value("csirsBmMgmtSubband", scf_value, self.name)


