class NumOfPdcchCandidates(BaseConvertor):

    name = "numOfPdcchCandidates"

    """
    "numOfPdcchCandidatesInAL4": {
    "check": {
      "attribute": "aggregationLevel",
      "equals": "AL4"
    },
    "mediationValues": {
      "n1": 1,
      "n2": 2,
      "n3": 3,
      "n4": 4,
      "n5": 5,
      "n6": 6,
      "n7": 7,
      "n8": 8
    },
    "defaultValue": 0,
    "mediatedAttributes": {
      "numOfPdcchCandidates": "value"
    }
    """

    @logging_decorator
    def convert(self):
        try:
            dedicated_bwp_profile = self._get_bwp_profile_distname()
            numOfpdcchcandidates_with_aggregation_level = self._get_numOfpdcchcandidates_with_aggregation_level(dedicated_bwp_profile)
            numOfpdcchcandidates = self._get_numOfpdcchcandidates_from_scf(dedicated_bwp_profile, numOfpdcchcandidates_with_aggregation_level)

            return self._get_mediated_attribute_value(numOfpdcchcandidates_with_aggregation_level, numOfpdcchcandidates, self.name)
        except ScfParameterNotExist as err:
            logging.warning("numOfPdcchCandidates convert failed because {}".format(err))
            return None

    def _get_bwp_profile_distname(self):
        bwpdn_list = self._scf.get_all_parameter_values(name="bwpDN", dist_name=self._cell_distname)
        if not bwpdn_list:
            raise ScfParameterNotExist("bwpDN not in {}".format(self._cell_distname))

        return bwpdn_list[-1]

    def _get_numOfpdcchcandidates_with_aggregation_level(self, dedicated_bwp_profile):
        dci_dedicated_aggregation_level = self._scf.get_all_parameter_values("dciDedicatedAggregationLevel",
                                                                             dist_name=dedicated_bwp_profile + "/PDCCH-1")
        if not dci_dedicated_aggregation_level:
            raise ScfParameterNotExist("dciDedicatedAggregationLevel not in {}".format(dedicated_bwp_profile))

        return self.name + "In" + dci_dedicated_aggregation_level[0]

    def _get_numOfpdcchcandidates_from_scf(self, dedicated_bwp_profile, name_with_aggregation_level):
        pdcch_config_dedicated_distname = dedicated_bwp_profile + "/PDCCH-1/PDCCH_CONFIG_DEDICATED-1"
        searchspace_types = self._scf.get_all_parameter_values("searchSpaceType", dist_name=pdcch_config_dedicated_distname)
        if not searchspace_types:
            raise ScfParameterNotExist("searchSpaceType not in {}".format(pdcch_config_dedicated_distname))

        numOfpdcchcandidates_from_scf = self._scf.get_all_parameter_values(name_with_aggregation_level,
                                                                           dist_name=pdcch_config_dedicated_distname)
        if not numOfpdcchcandidates_from_scf:
            raise ScfParameterNotExist("{} not in {}".format(name_with_aggregation_level, pdcch_config_dedicated_distname))

        numOfpdcchcandidates = "n5"
        for index in range(len(searchspace_types)):
            if searchspace_types[index] == "UE-Specific":
                numOfpdcchcandidates = numOfpdcchcandidates_from_scf[index]
        return numOfpdcchcandidates


class InitialCRbStartUl(BaseConvertor):

    name = "initialCRbStartUl"

    """
    Internal name: initialCRbStartUl
    This parameter indicates the index of the first Common Resource Block of the uplink BWP within the cell.
    This is the cRbStartUl of the initial BWP.

    """

    @logging_decorator
    def convert(self):
        try:
            dedicated_bwp_profile = self._get_bwp_profile_distname()

            crb_startul = self._scf.get_all_parameter_values(name="cRbStartUl", dist_name=dedicated_bwp_profile)
            if not crb_startul:
                raise ScfParameterNotExist("cRbStartUl can not be found in {}".format(dedicated_bwp_profile))
            crb_startul = crb_startul[0]

            return self._get_mediated_attribute_value(self.name, crb_startul, self.name)
        except ScfParameterNotExist as err:
            logging.warning("'bwpDN' or 'cRbStartUl' get from scf failed, {}, use default value".format(err))
            return None

    def _get_bwp_profile_distname(self):
        bwpdn_list = self._scf.get_all_parameter_values(name="bwpDN", dist_name=self._cell_distname)
        if not bwpdn_list:
            raise ScfParameterNotExist("bwpDN not in {}".format(self._cell_distname))

        return bwpdn_list[0]


