class ActSlowPrbPooling(BaseConvertor):

    name = "actSlowPrbPooling"

    """
    Internal name: actSlowPrbPooling
    Identifier of the PRB Pooling Group (0 or 1).

    "actSlowPrbPooling": {
        "check": {
            "attribute": "cellTechnology",
            "equals": "FDD"
        },
        "mediationValues": {
            "false": 0,
            "true": 1
        },
        "defaultValue": 0,
        "mediatedAttributes": {
        "actSlowPrbPooling": "value"
        }
    }
    """

    ACTIVE = 1

    @logging_decorator
    def convert(self):
        try:
            cell_technology = self._get_scf_parameter_value("cellTechnology", cell_distname=self._cell_distname)
            if cell_technology != "TDD":
                return self.ACTIVE

            scf_value = self._get_scf_parameter_value("actSlowPrbPooling", cell_distname=self._cell_distname)
            return self._get_mediated_attribute_value("actSlowPrbPooling", scf_value, self.name)
        except ScfParameterNotExist:
            return self.ACTIVE


